                    {
                        if (list.Remove(handler))
                        {
                            removed = true;
                            if (list.Count == 0)
                                emptybuckets.Add(prio);
                        }
                    }

                    foreach (var prio in emptybuckets)
                        buckets.Remove(prio);
                }

                return removed;
