                foreach (var order in channels)
                    result |= Call<T>(order, value);

                return result;
            }

            public bool Call<T>(double order, T value)
            {
                order = Normalize(order);
                var handlers = GetValueCopy(order);
                if (handlers == null || handlers.Length == 0) return false;
                var result = false;
                foreach (var handler in handlers)
                {
                    try
                    {
                        switch (handler)
                        {
                            case Action<T> h1: h1(value); result = true; break;
                            case Action h2: h2(); result = true; break;
                        }
                    }
                    catch (Exception ex)
                    {
                        Logger.LogError($"[SOS.API] Observer error in handler '{handler.Method.Name}' at order {order}: {ex.Message}");
                    }
                }

                return result;
            }

            public bool CallRange(double min = double.MinValue, double max = double.MaxValue)
            {
                bool result = false;

                foreach (var order in GetKeyCopy(min, max))
                    result |= Call(order);

                return result;
            }

            public bool CallRange<T>(T value, double min = double.MinValue, double max = double.MaxValue)
            {
                List<double> channels = GetKeyCopy(min, max);
                bool result = false;

                foreach (var order in channels)
                    result |= Call<T>(order, value);

                return result;
            }

            /// <summary>
            /// Clears all event channels and state entries.
            /// </summary>
            /// <remarks>
            /// Clears the internal dictionary of channels (_channels) and the state dictionary (_state).
            /// All handlers are removed, and any stored state is cleared. This operation is performed under locks
            /// to ensure thread safety.
            /// </remarks>
            public void Clear()
            {
                lock (buckets) buckets.Clear();
            }
        }

        /// <summary>
        /// Subscribes a strongly-typed callback to the specified event channel with priority-based execution ordering.
        /// </summary>
        /// <typeparam name="T">The payload type associated with the event.</typeparam>
        /// <param name="key">The unique event identifier channel.</param>
        /// <param name="handler">The delegate to invoke when the event is emitted.</param>
