        {
            lock (_channels)
            {
                if (!_channels.TryGetValue(key, out var channel))
                    _channels[key] = channel = new();

                channel.Add(handler, order);
            }

            Logger.LogDebug($"ON '{key}' (T:{typeof(T).FullOrName()}) registered at order {order}.", level: LogLevel.Trace);
        }

